"use client";
import { useState } from "react";
import { Tabs, TabsList, TabsTrigger, TabsContent } from "@/components/ui/tabs";
import { Card, CardHeader, CardTitle, CardContent } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Avatar, AvatarImage, AvatarFallback } from "@/components/ui/avatar";

const UPCOMING = [
  {
    id: 1,
    doctor: {
      name: "Dr. Mehta",
      specialization: "Cardiologist",
      avatar: "https://randomuser.me/api/portraits/men/32.jpg",
    },
    date: "2024-06-10",
    time: "17:30",
    status: "Confirmed",
  },
  {
    id: 2,
    doctor: {
      name: "Dr. Sharma",
      specialization: "Dermatologist",
      avatar: "https://randomuser.me/api/portraits/women/44.jpg",
    },
    date: "2024-06-12",
    time: "11:00",
    status: "Pending",
  },
];

const PAST = [
  {
    id: 3,
    doctor: {
      name: "Dr. Patel",
      specialization: "Pediatrician",
      avatar: "https://randomuser.me/api/portraits/men/65.jpg",
    },
    date: "2024-05-20",
    time: "09:00",
    status: "Completed",
  },
  {
    id: 4,
    doctor: {
      name: "Dr. Gupta",
      specialization: "Orthopedic",
      avatar: "https://randomuser.me/api/portraits/men/12.jpg",
    },
    date: "2024-05-10",
    time: "15:00",
    status: "Cancelled",
  },
];

const statusColor = {
  Confirmed: "green",
  Pending: "yellow",
  Cancelled: "red",
  Completed: "blue",
};

function formatDate(dateStr) {
  const d = new Date(dateStr);
  return d.toLocaleDateString(undefined, { month: "short", day: "numeric", year: "numeric" });
}

function isToday(dateStr) {
  const today = new Date();
  const d = new Date(dateStr);
  return d.toDateString() === today.toDateString();
}

export default function MyAppointmentsPage() {
  const [tab, setTab] = useState("upcoming");

  return (
    <div className="max-w-6xl mx-11 px-2">
      <h1 className="text-2xl font-bold mb-6 text-blue-600">My Appointments</h1>
      <Tabs value={tab} onValueChange={setTab} className="mb-6">
        <TabsList>
          <TabsTrigger value="upcoming">Upcoming</TabsTrigger>
          <TabsTrigger value="past">Past</TabsTrigger>
        </TabsList>
        <TabsContent value="upcoming">
          <AppointmentList appointments={UPCOMING} type="upcoming" />
        </TabsContent>
        <TabsContent value="past">
          <AppointmentList appointments={PAST} type="past" />
        </TabsContent>
      </Tabs>
    </div>
  );
}

function AppointmentList({ appointments, type }) {
  if (!appointments.length) {
    return (
      <div className="flex flex-col items-center justify-center py-16">
        <span className="text-6xl mb-4">📅</span>
        <div className="text-gray-500 text-lg">No {type === "upcoming" ? "upcoming" : "past"} appointments found.</div>
      </div>
    );
  }
  return (
    <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
      {appointments.map((appt) => (
        <Card key={appt.id} className="rounded-xl shadow p-4 hover:shadow-lg transition flex flex-col gap-3">
          <CardHeader className="flex flex-row items-center gap-4 p-0 pb-2 border-b border-gray-100">
            <Avatar className="w-12 h-12">
              <AvatarImage src={appt.doctor.avatar} alt={appt.doctor.name} />
              <AvatarFallback>{appt.doctor.name.charAt(0)}</AvatarFallback>
            </Avatar>
            <div className="flex-1">
              <CardTitle className="text-lg font-semibold text-gray-800 mb-1">{appt.doctor.name}</CardTitle>
              <div className="text-blue-600 text-sm font-medium">{appt.doctor.specialization}</div>
            </div>
            <Badge color={statusColor[appt.status]}>{appt.status}</Badge>
          </CardHeader>
          <CardContent className="flex flex-col gap-2 p-0 pt-2">
            <div className="text-gray-600 text-sm">
              <span className="font-medium">Date:</span> {formatDate(appt.date)}
            </div>
            <div className="text-gray-600 text-sm">
              <span className="font-medium">Time:</span> {appt.time}
            </div>
            <div className="flex gap-2 mt-2">
              {type === "upcoming" && isToday(appt.date) && (
                <Button size="sm" className="bg-blue-600 text-white hover:bg-blue-700">Join Video</Button>
              )}
              {type === "upcoming" && appt.status !== "Cancelled" && (
                <Button size="sm" variant="outline" className="text-gray-600 border-gray-300 hover:bg-gray-100">Cancel Appointment</Button>
              )}
            </div>
          </CardContent>
        </Card>
      ))}
    </div>
  );
} 